const content = $('Groq Route Parser').item.json.choices[0].message.content;
const start = content.indexOf('{');
const end = content.lastIndexOf('}');
const raw = content.substring(start, end + 1);

// Прибираємо \n та \r — Groq часто їх вставляє незважаючи на промпт
const clean = raw.replace(/\n/g, '').replace(/\r/g, '');

const routeData = JSON.parse(clean);

let sessionData = {};
try {
  sessionData = JSON.parse($('Get Session').item.json.data || '{}');
} catch(e) {
  sessionData = {};
}

const merged = Object.assign(sessionData, routeData);
return [{ json: { merged: JSON.stringify(merged) } }];

const raw = $('Clean Groq Response').item.json.merged;
const data = JSON.parse(raw);

// Автогенерація службових полів
// CONTRACT_DATE — сьогоднішня дата у форматі "16.05.2026"
data.CONTRACT_DATE = $now.toFormat('dd.MM.yyyy');

// CONTRACT_NUMBER — унікальний номер на основі часу (наприклад: 290526-1423)
// Формат: день+місяць+рік_год+хвилина — завжди унікальний для кожного договору
data.CONTRACT_NUMBER = $now.toFormat('ddMMyy') + '-' + $now.toFormat('HHmm');
data.TRANSPORT_TYPE = 'Вантажоперевезення';
const requests = Object.entries(data).map(([key, value]) => ({
  replaceAllText: {
    containsText: { text: `{{${key}}}`, matchCase: true },
    replaceText: String(value || '')
  }
}));

return [{ json: { requests } }];

